// Generated by vibelang from src/providers/catalog/plugin.ts; the migrate flow writes it again with each batch.
export function pluginLabel(plugin) {
    if (plugin.id)
        return plugin.id;
    if (plugin.source.type === "package")
        return plugin.source.target;
    if (plugin.source.type === "local")
        return plugin.source.path;
    return plugin.source.type;
}
export function pluginLabels(plugins) {
    return plugins.flatMap((plugin) => (plugin.source.type === "builtin" ? [] : [pluginLabel(plugin)]));
}
